args.CommandLine:
cat > do_refactor2.ts << 'EOF'
import { Project, SyntaxKind, ObjectLiteralExpression, Node, ReturnStatement } from "ts-morph";
import * as fs from "fs";

const project = new Project();
project.addSourceFilesAtPaths("src/store/player.ts");

const sourceFile = project.getSourceFileOrThrow("src/store/player.ts");

const slices = {
  queue: ["queue", "shuffledQueue", "currentIndex", "currentTrack", "isPlaying", "volume", "muted", "repeat", "shuffle", "autoplay", "normalization", "crossfade", "playTrack", "playList", "togglePlay", "playNext", "playPrev", "seek", "seekRelative", "setVolume", "toggleMute", "toggleShuffle", "cycleRepeat", "toggleAutoplay", "setNormalization", "setCrossfade", "addToQueueNext", "addToQueueEnd", "removeFromQueue", "reorderQueue", "clearQueue", "jumpToQueueIndex"],
  playlist: ["customPlaylists", "createPlaylist", "createSmartPlaylist", "deletePlaylist", "renamePlaylist", "setPlaylistCover", "addToPlaylist", "removeFromPlaylist", "reorderInPlaylist", "importPlaylist", "sharePlaylist", "addPlaylistCollaborator", "reorderCustomPlaylists"],
  ui: ["view", "navHistory", "searchQuery", "searchFocus", "commandOpen", "rightPanelOpen", "fullscreenPlayer", "lyricsOpen", "queueOpen", "helpOpen", "miniPlayer", "karaokeMode", "lyricsOffset", "visualizerOpen", "theme", "flatBackdrop", "contextMenu", "toast", "lyricsLoading", "lyricsStatus", "lyricsPlain", "aligning", "syncReady", "sleepTimer", "locale", "navigate", "back", "setSearch", "setSearchFocus", "setCommandOpen", "toggleRightPanel", "toggleFullscreenPlayer", "toggleLyrics", "toggleQueue", "setHelpOpen", "toggleMiniPlayer", "toggleKaraoke", "adjustLyricsOffset", "resetLyricsOffset", "toggleVisualizer", "closeVisualizer", "setTheme", "setFlatBackdrop", "closeFullscreenPlayer", "openContextMenu", "openAlbumContextMenu", "openArtistContextMenu", "closeContextMenu", "notify", "dismissToast", "setLocale", "startSleepTimer", "sleepAfterTrack", "cancelSleepTimer"],
  playback: ["favorites", "dislikes", "recentTrackhashes", "playCounts", "selectionMode", "selected", "scrobble", "recordSkip", "toggleFavorite", "isFavorite", "toggleDislike", "isDisliked", "enterSelection", "toggleSelected", "selectMany", "clearSelection", "exitSelection", "generateAiPlaylist", "hydrateLocal", "hydrateFromServer", "restoreLastSession", "resetServerStats", "fetchLyrics", "alignLyrics", "startRadio", "startTrajectory", "startBlend"]
};

const usePlayerDecl = sourceFile.getVariableDeclarationOrThrow("usePlayer");
const createCall = usePlayerDecl.getInitializerIfKindOrThrow(SyntaxKind.CallExpression);
const factoryArrow = createCall.getArguments()[0];
if (!Node.isArrowFunction(factoryArrow)) throw new Error("Expected arrow");

const factoryBody = factoryArrow.getBody();
let objLiteral: ObjectLiteralExpression | undefined;
if (Node.isBlock(factoryBody)) {
  const retStmt = factoryBody.getStatements().find(s => Node.isReturnStatement(s)) as ReturnStatement;
  objLiteral = retStmt.getExpressionIfKindOrThrow(SyntaxKind.ObjectLiteralExpression);
} else if (Node.isObjectLiteralExpression(factoryBody)) {
  objLiteral = factoryBody;
}

let pushPlaylistCode = "";
if (Node.isBlock(factoryBody)) {
    for (const stmt of factoryBody.getStatements()) {
        if (!Node.isReturnStatement(stmt)) {
            pushPlaylistCode += stmt.getText() + "\n";
        }
    }
}

const sliceContents: Record<string, string[]> = { queue: [], playlist: [], ui: [], playback: [] };

const persistCalls = sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression).filter(c => {
  const expr = c.getExpression();
  return Node.isIdentifier(expr) && expr.getText() === "persist";
});
for (const pc of persistCalls) {
  const parent = pc.getParent();
  if (Node.isExpressionStatement(parent)) parent.remove();
}

for (const prop of objLiteral!.getProperties()) {
  let name = "";
  if (Node.isPropertyAssignment(prop)) name = prop.getName();
  else if (Node.isMethodDeclaration(prop)) name = prop.getName();
  else if (Node.isShorthandPropertyAssignment(prop)) name = prop.getName();
  else continue;

  let assignedSlice = "misc";
  for (const [sName, sProps] of Object.entries(slices)) {
    if (sProps.includes(name)) { assignedSlice = sName; break; }
  }
  if (assignedSlice !== "misc") sliceContents[assignedSlice].push(prop.getText());
}

for (const [sName, props] of Object.entries(sliceContents)) {
  const pickKeys = slices[sName as keyof typeof slices].map(k => `"${k}"`).join(" | ");

  const content = `import { StateCreator } from "zustand";\n` +
    `import type { PlayerState } from "./types";\n` +
    `import { api } from "@/lib/auralis/api";\n` +
    `import { useLibraryStore, tracksForHashes } from "../library";\n` +
    `import { useReco, fetchRadio, fetchTrajectory, fetchBlend } from "../reco";\n` +
    `import { usePlayhead } from "../playhead";\n` +
    `import { audioEl, clearResumeSeek, exemptFromSkip, pendingResumeSeek, hydrated } from "./PlaybackController";\n` +
    `import { applyTheme, normalizeTheme } from "@/lib/auralis/themes";\n` +
    `import { shuffleArray, reorderWithFirst, buildContinuation, clampOffset, DEFAULT_LYRICS_OFFSET, parseRules, loadPersisted, initialLocale, initialTheme, initial, nextToastSeq } from "./helpers";\n\n` +
    (sName === "playlist" ? pushPlaylistCode + "\n" : "") +
    `export const create${sName.charAt(0).toUpperCase() + sName.slice(1)}Slice: StateCreator<PlayerState, [], [], Pick<PlayerState, ${pickKeys}>> = (set, get) => ({\n` +
    props.join(",\n\n") +
    `\n});\n`;
  fs.writeFileSync(`src/store/slices/${sName}Slice.ts`, content);
}
EOF
npx tsx do_refactor2.ts
